#include <iostream>
#include <initializer_list>
#include <memory>
#include <stdexcept>

class IntArray {
private:
    size_t size_;
    std::unique_ptr<int[]> data_;
public:
    IntArray(std::initializer_list<int> list)
        : size_(list.size()), data_(std::make_unique<int[]>(list.size())) {
        size_t idx = 0;
        for (int val : list) {
            data_[idx++] = val;
        }
    }

    size_t size() const noexcept { return size_; }

    // Non-const: returns reference for assignment
    int& operator[](size_t index) {
        if (index >= size_) {
            throw std::out_of_range("Index out of range");
        }
        return data_[index];
    }

    // Const: returns element value (or const reference) for read-only access
    int operator[](size_t index) const {
        if (index >= size_) {
            throw std::out_of_range("Index out of range");
        }
        return data_[index];
    }
};

void printConstArray(const IntArray& arr) {
    std::cout << "Const read: ";
    for (size_t i = 0; i < arr.size(); ++i) {
        std::cout << arr[i] << " ";
    }
    std::cout << "\n";
}

int main() {
    IntArray arr = {10, 20, 30, 40};
    arr[1] = 99; // Non-const operator[]
    printConstArray(arr); // Const operator[]
    return 0;
}

#include <iostream>

class HugeInt {
private:
    long value_;
public:
    HugeInt(long val = 0) : value_(val) {}
    long value() const { return value_; }

    // Member operator+: handles HugeInt + long and HugeInt + HugeInt
    HugeInt operator+(long rhs) const {
        return HugeInt(value_ + rhs);
    }
};

// Non-member operator+: handles long + HugeInt to provide commutativity
// Reuses the member operator+ by swapping operands
HugeInt operator+(long lhs, const HugeInt& rhs) {
    return rhs + lhs;
}

int main() {
    HugeInt big(100);
    long num = 25;

    HugeInt res1 = big + num; // Member operator+
    HugeInt res2 = num + big; // Non-member operator+

    std::cout << "res1: " << res1.value() << "\n";
    std::cout << "res2: " << res2.value() << "\n";
    return 0;
}

#include <iostream>

class NumberBox {
private:
    int value_;
public:
    // Explicit single-argument constructor prevents silent conversion from int
    explicit NumberBox(int val) : value_(val) {}

    int getValue() const { return value_; }

    // Explicit conversion operator to double
    explicit operator double() const {
        return static_cast<double>(value_);
    }
};

void display(const NumberBox& box) {
    std::cout << "Box value: " << box.getValue() << "\n";
}

int main() {
    // display(42); // COMPILE ERROR: cannot implicitly convert int to NumberBox
    display(NumberBox(42)); // OK: explicit construction

    NumberBox nb(15);
    // double d = nb; // COMPILE ERROR: cannot implicitly convert with explicit operator
    double d = static_cast<double>(nb); // OK: explicit cast
    std::cout << "Double cast: " << d << "\n";

    return 0;
}
